+            GeoShapeCellValues values = new GeoShapeCellValues(makeGeoShapeValues(value), tiler, circuitBreakerConsumer);
+            assertTrue(values.advanceExact(0));
+            assertThat(values.getValuesBytes(), equalTo(curNumBytes));
