-    static Geometry boxToGeo(GeoBoundingBox geoBox) {
-        // turn into polygon
-        if (geoBox.right() < geoBox.left() && geoBox.right() != -180) {
-            return new MultiPolygon(List.of(
-                new Polygon(new LinearRing(
-                    new double[] { -180, geoBox.right(), geoBox.right(), -180, -180 },
